function colorize(mc, colorNumber)
{
   var _loc3_ = new Color(mc);
   var _loc2_ = 16777215 - colorNumber;
   var _loc5_ = (_loc2_ & 0xFF0000) >> 16;
   var _loc6_ = (_loc2_ & 0xFF00) >> 8;
   var _loc4_ = _loc2_ & 0xFF;
   var _loc1_ = _loc3_.getTransform();
   _loc1_.rb = - _loc5_;
   _loc1_.gb = - _loc6_;
   _loc1_.bb = - _loc4_;
   _loc3_.setTransform(_loc1_);
}
function animationComplete()
{
   interactionCompleteCallback(puffleID);
}
function interact(colour, name)
{
   stopPuffle();
   animatePuffle();
   pufflecolour = colour;
   colorize(puffle_mc.puffleGrooming.body,pufflecolour);
}
function stopInteract()
{
   stopPuffle();
}
function animatePuffle()
{
   puffle_mc.gotoAndPlay("play");
   cutNumber = 1;
   colorize(puffle_mc.puffleGrooming.body,pufflecolour);
   hairCuts.splice(0,12,"Haircut_1","Haircut_2","Haircut_3","Haircut_4","Haircut_5","Haircut_6","Haircut_7","Haircut_8","Haircut_9","Haircut_10","Haircut_11","Haircut_12");
}
function animations()
{
   if(cutNumber == 1)
   {
      anim();
   }
   else if(cutNumber == 2)
   {
      anim();
   }
   else if(cutNumber == 3)
   {
      anim();
   }
   else if(cutNumber == 4)
   {
      anim();
   }
   else if(cutNumber == 5)
   {
      animStop();
   }
}
function anim()
{
   currCut = random(hairCuts.length);
   puffle_mc.gotoAndStop(hairCuts[currCut]);
   hairCuts.splice(currCut,1);
   cutNumber += 1;
   colorize(puffle_mc.puffleGrooming.body,pufflecolour);
}
function animStop()
{
   puffle_mc.gotoAndPlay("End_part1");
   colorize(puffle_mc.puffleGrooming.body,pufflecolour);
}
function stopPuffle()
{
   puffle_mc.gotoAndStop("park");
}
stop();
var pufflecolour;
var puffleID;
var interactionCompleteCallback;
var currCut;
var cutNumber;
var hairCuts = new Array();
onEnterFrame = function()
{
   if(puffle_mc._currentframe == 185)
   {
      animations();
   }
   if(puffle_mc._currentframe == 341)
   {
      animationComplete();
   }
};
